INSERT INTO providers (id,slug,listing_type,name,description,website_url,source_url,listing_status,claim_status,origin,provider_classification)
SELECT 'independent-fay-victor','fay-victor-vocal-instruction-independent-fay-victor','coach','Fay Victor Vocal Instruction','Fay Victor offers private vocal instruction through her East Flatbush private practice, as well as separate group improvisation workshops. Internationally recognized educator and performing vocalist with more than 15 years of improvisational performance experience.','https://www.fayvictor.com/vocal-instruction/','https://www.fayvictor.com/vocal-instruction/','published','unclaimed','seeded','independent_teacher'
WHERE NOT EXISTS (SELECT 1 FROM providers WHERE lower(trim(name))=lower(trim('Fay Victor Vocal Instruction')) AND lower(trim(website_url))=lower(trim('https://www.fayvictor.com/vocal-instruction/')));
